import urllib.request
import os
import json
import pandas as pd

# Constants
TARGET_JSON_FILE = "downloaded_file.json"


def task_func(url):
    try:
        urllib.request.urlretrieve(url, TARGET_JSON_FILE)
        with open(TARGET_JSON_FILE, "r", encoding="utf-8") as file_handle:
            data = json.load(file_handle)
        return pd.DataFrame(data)
    finally:
        if os.path.exists(TARGET_JSON_FILE):
            try:
                os.remove(TARGET_JSON_FILE)
            except OSError:
                pass
